class EscenaMenu extends Phaser.Scene {
  constructor() { super('Menu'); }
  create() {
    this.input.keyboard.once('keydown-SPACE', () => {
      this.scene.start('Nivel', { dificultad: 'normal', vidas: 3 });
    });
  }
}

class EscenaNivel extends Phaser.Scene {
  constructor() { super('Nivel'); }
  init(datos) {
    this.dificultad = datos.dificultad;
    this.vidas = datos.vidas;
  }
  create() {
    this.add.text(20, 20, `Nivel ${this.dificultad} — Vidas: ${this.vidas}`);
  }
}

class EscenaJuego extends Phaser.Scene {
  constructor() { super('Juego'); }
  create() {
    this.add.text(20, 20, 'Partida');
    this.input.keyboard.once('keydown-ESC', () => {
      this.scene.launch('Pausa');
      this.scene.pause();
    });
  }
}

class EscenaPausa extends Phaser.Scene {
  constructor() { super('Pausa'); }
  create() {
    this.add.text(300, 200, 'PAUSA');
    this.input.keyboard.once('keydown-ENTER', () => {
      this.scene.stop();
      this.scene.resume('Juego');
    });
  }
}

class EscenaMovimiento extends Phaser.Scene {
  create() {
    this.caja = this.add.rectangle(50, 150, 40, 40, 0x55ddbb).setOrigin(0.5);
    this.velocidad = 180; // píxeles por segundo
