create() {
  this.jugador = this.add.rectangle(400, 225, 40, 40, 0x59d6b5);
  this.cursor = this.input.keyboard.createCursorKeys();
  this.velocidad = 220;
}

update(time, delta) {
  const paso = this.velocidad * delta / 1000;
  if (this.cursor.left.isDown) this.jugador.x -= paso;
  if (this.cursor.right.isDown) this.jugador.x += paso;
  if (this.cursor.up.isDown) this.jugador.y -= paso;
  if (this.cursor.down.isDown) this.jugador.y += paso;
}

update(time, delta) {
  const paso = this.velocidad * delta / 1000;
  if (this.cursor.left.isDown) this.jugador.x -= paso;
  if (this.cursor.right.isDown) this.jugador.x += paso;

  const mitad = this.jugador.width / 2;
  this.jugador.x = Phaser.Math.Clamp(
    this.jugador.x,
    mitad,
    this.scale.width - mitad
  );
}

update(time, delta) {
  let dx = 0;
  let dy = 0;
  if (this.cursor.left.isDown) dx--;
  if (this.cursor.right.isDown) dx++;
  if (this.cursor.up.isDown) dy--;
  if (this.cursor.down.isDown) dy++;

  const longitud = Math.hypot(dx, dy) || 1;
  const paso = this.velocidad * delta / 1000;
  this.jugador.x += (dx / longitud) * paso;
  this.jugador.y += (dy / longitud) * paso;
}

